#include "Aevrynd/CharacterController3D.h"
#include <algorithm>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <limits>
#include <new>
#include <vector>

namespace {std::atomic<std::uint64_t> allocationCount{};}
void* operator new(std::size_t size){allocationCount.fetch_add(1,std::memory_order_relaxed);if(void* memory=std::malloc(size?size:1))return memory;throw std::bad_alloc();}

using namespace Aevrynd;
namespace {
bool Near(float a,float b,float e=.001f){return std::abs(a-b)<=e;}
bool Near(Vec3 a,Vec3 b,float e=.001f){return Near(a.x,b.x,e)&&Near(a.y,b.y,e)&&Near(a.z,b.z,e);}
int Fail(const char* message){std::cerr<<message<<'\n';return 1;}
bool SameResult(const CharacterDirectDisplacementResult3D& a,const CharacterDirectDisplacementResult3D& b){return std::memcmp(&a,&b,sizeof(a))==0;}
}

int main(){
    const std::vector<BoxCollider3D> empty;
    CharacterController3D freeMotion;if(!freeMotion.PrepareDirectDisplacement(128))return Fail("prepare failed");freeMotion.Reset({});CharacterDirectDisplacementResult3D result{};
    if(!freeMotion.ApplyDirectDisplacementTick({1,{1,0,2},.5f},empty,&result)||result.status!=CharacterDirectDisplacementStatus3D::Applied||!Near(freeMotion.Position(),{1,0,2})||!Near(freeMotion.Yaw(),.5f)||!Near(result.requestedWorld,result.consumedWorld+result.remainderWorld)||result.consumedYawRadians!=.5f||result.remainderYawRadians!=0)return Fail("free translation/yaw transaction failed");
    if(!freeMotion.ApplyDirectDisplacementTick({2,{},0},empty,&result)||result.status!=CharacterDirectDisplacementStatus3D::NoMotion)return Fail("no-motion transaction failed");
    const auto stateBefore=freeMotion.StateHash();CharacterDirectDisplacementResult3D sentinel{};std::memset(&sentinel,0xa5,sizeof(sentinel));const auto sentinelBefore=sentinel;if(freeMotion.ApplyDirectDisplacementTick({4,{1,0,0},0},empty,&sentinel)||freeMotion.StateHash()!=stateBefore||!SameResult(sentinel,sentinelBefore))return Fail("discontinuous tick was not atomic");

    const std::vector<BoxCollider3D> wall={{{2,1,0},{.1f,2,20}}};CharacterController3D slide;slide.Reset({});
    if(!slide.ApplyDirectDisplacementTick({1,{3,0,2},.25f},wall,&result)||result.status!=CharacterDirectDisplacementStatus3D::Blocked||!Near(slide.Position(),{1.45f,0,2},.002f)||!Near(result.remainderWorld,{1.55f,0,0},.002f)||!Near(slide.Yaw(),.25f)||result.remainderYawRadians!=0)return Fail("wall slide/partial consumption failed");
    const auto blockedPosition=slide.Position();if(!slide.ApplyDirectDisplacementTick({2,{},0},wall,&result)||result.status!=CharacterDirectDisplacementStatus3D::NoMotion||!Near(slide.Position(),blockedPosition)||!std::isfinite(result.deterministicHash))return Fail("blocked contact poisoned the next tick");
    const float wallTouch=wall[0].center.x-(wall[0].extents.x+.45f);CharacterController3D touchInto,touchAway,touchTangent;touchInto.Reset({wallTouch,0,0});touchAway.Reset({wallTouch,0,0});touchTangent.Reset({wallTouch,0,0});if(!touchInto.ApplyDirectDisplacementTick({1,{1,0,0},.1f},wall,&result)||result.status!=CharacterDirectDisplacementStatus3D::Blocked||!Near(touchInto.Position(),{wallTouch,0,0})||!Near(touchInto.Yaw(),.1f)){std::cerr<<"touchInto status="<<int(result.status)<<" x="<<touchInto.Position().x<<" boundary="<<wallTouch<<'\n';return Fail("initial touch into was not blocked");}if(!touchAway.ApplyDirectDisplacementTick({1,{-1,0,0},0},wall,&result)||result.status!=CharacterDirectDisplacementStatus3D::Applied||!Near(touchAway.Position(),{wallTouch-1,0,0}))return Fail("initial touch away was blocked");if(!touchTangent.ApplyDirectDisplacementTick({1,{0,0,1},0},wall,&result)||result.status!=CharacterDirectDisplacementStatus3D::Applied||!Near(touchTangent.Position(),{wallTouch,0,1}))return Fail("initial touch tangent was blocked");
    const std::vector<BoxCollider3D> reversedCorner={{{0,1,2},{20,2,.1f}},{{2,1,0},{.1f,2,20}}},forwardCorner={reversedCorner.rbegin(),reversedCorner.rend()};CharacterController3D cornerA,cornerB;cornerA.Reset({});cornerB.Reset({});if(!cornerA.ApplyDirectDisplacementTick({1,{3,0,3},0},reversedCorner,&result)||!cornerB.ApplyDirectDisplacementTick({1,{3,0,3},0},forwardCorner,&result)||!Near(cornerA.Position(),cornerB.Position())||!Near(cornerA.Position(),{1.45f,0,1.45f},.002f))return Fail("simultaneous corner was order dependent");
    const std::vector<BoxCollider3D> thinWall={{{0,1,5},{20,2,.001f}}};CharacterController3D tunneling;tunneling.Reset({});if(!tunneling.ApplyDirectDisplacementTick({1,{0,0,10},0},thinWall,&result)||tunneling.Position().z>4.551f)return Fail("thin-wall sweep tunneled");

    const std::vector<BoxCollider3D> overlap={{{0,.9f,0},{1,1,1}}};CharacterController3D inside;inside.Reset({});if(!inside.ApplyDirectDisplacementTick({1,{3,0,0},.3f},overlap,&result)||result.status!=CharacterDirectDisplacementStatus3D::StartedOverlapping||!Near(inside.Position(),{})||!Near(inside.Yaw(),.3f)||!Near(result.remainderWorld,{3,0,0})||inside.Stats().directOverlaps!=1)return Fail("initial overlap safe transaction failed");

    HeightField3D terrain({{-2,1,-2},5,5,1});terrain.Fill(1);CharacterController3D grounded;grounded.Reset({0,2,0});if(!grounded.ApplyDirectDisplacementTick({1,{0,-2,0},0},empty,terrain,&result)||!grounded.Grounded()||!Near(grounded.Position().y,1)||!Near(result.groundCorrectionWorld.y,1)||!Near(result.consumedWorld.y,-2)||!Near(result.requestedWorld,result.consumedWorld+result.remainderWorld))return Fail("terrain correction accounting failed");if(!grounded.ApplyDirectDisplacementTick({2,{0,.2f,0},0},empty,terrain,&result)||grounded.Grounded()||!Near(grounded.Position().y,1.2f))return Fail("ascending terrain motion snapped down");
    const std::vector<BoxCollider3D> platform={{{0,-.5f,0},{1,.5f,1}}};CharacterController3D support;support.Reset({});if(!support.ApplyDirectDisplacementTick({1,{},0},platform,&result)||!support.Grounded())return Fail("static support was not detected");if(!support.ApplyDirectDisplacementTick({2,{3,0,0},0},platform,&result)||support.Grounded())return Fail("walking off support retained grounded");

    CollisionWorld3D filteredWorld;filteredWorld.CreateBox({{{0,1,2},{20,2,.1f}},4,1,1,true});filteredWorld.CreateBox({{{0,1,4},{20,2,.1f}},2,1,2,false});CharacterController3D filtered;if(!filtered.PrepareDirectDisplacement(2))return Fail("world prepare failed");filtered.Reset({});if(!filtered.ApplyDirectDisplacementTick({1,{0,0,10},0},filteredWorld,{2,1,false},&result)||filtered.Position().z>3.451f)return Fail("world layer filter failed");const auto activeScratchHash=filtered.StateHash();sentinel=sentinelBefore;if(filtered.ApplyDirectDisplacementTick({3,{1,0,0},0},filteredWorld,{4,1,true},&sentinel)||filtered.StateHash()!=activeScratchHash||!SameResult(sentinel,sentinelBefore))return Fail("failed world transaction changed active scratch");CharacterController3D trigger;if(!trigger.PrepareDirectDisplacement(2))return Fail("trigger prepare failed");trigger.Reset({});if(!trigger.ApplyDirectDisplacementTick({1,{0,0,10},0},filteredWorld,{4,1,true},&result)||trigger.Position().z>1.451f)return Fail("trigger include filter failed");CharacterController3D capacity;capacity.Reset({});const auto capacityHash=capacity.StateHash();if(capacity.ApplyDirectDisplacementTick({1,{1,0,0},0},filteredWorld,{},&sentinel)||capacity.StateHash()!=capacityHash)return Fail("unprepared world capacity was accepted");

    CharacterController3D teleported;if(!teleported.Teleport({5,2,-3},7.f,40)||!teleported.ApplyDirectDisplacementTick({41,{1,0,0},.1f},empty,&result)||!Near(teleported.Position(),{6,2,-3})||teleported.Yaw()<=-3.141593f||teleported.Yaw()>3.141593f)return Fail("teleport/yaw normalization failed");if(teleported.Teleport({},0,(std::numeric_limits<uint64_t>::max)()))return Fail("maximum tick teleport accepted");teleported.Reset({});if(!teleported.ApplyDirectDisplacementTick({1,{},0},empty,&result))return Fail("reset did not restore tick one");

    CharacterController3D hostile;hostile.Reset({});sentinel=sentinelBefore;const auto hostileHash=hostile.StateHash();const auto hostilePosition=hostile.Position();const auto hostileStats=hostile.Stats();if(hostile.ApplyDirectDisplacementTick({1,{(std::numeric_limits<float>::quiet_NaN)(),0,0},0},empty,&sentinel)||hostile.StateHash()!=hostileHash||!Near(hostile.Position(),hostilePosition)||!SameResult(sentinel,sentinelBefore))return Fail("non-finite input was not atomic");const auto hostileStatsAfter=hostile.Stats();if(std::memcmp(&hostileStatsAfter,&hostileStats,sizeof(hostileStats)))return Fail("failed transaction changed stats");const std::vector<BoxCollider3D> invalidBox={{{(std::numeric_limits<float>::max)(),0,0},{(std::numeric_limits<float>::max)(),1,1}}};if(hostile.ApplyDirectDisplacementTick({1,{1,0,0},0},invalidBox,&sentinel)||hostile.StateHash()!=hostileHash)return Fail("invalid collider was accepted");if(hostile.ApplyDirectDisplacementTick({1,{101,0,0},0},empty,&sentinel)||hostile.StateHash()!=hostileHash)return Fail("maximum displacement was not enforced");CharacterControllerSettings3D hugeSettings;hugeSettings.maximumDirectDisplacement=(std::numeric_limits<float>::max)();CharacterController3D overflow{hugeSettings};overflow.Reset({(std::numeric_limits<float>::max)(),0,0});const auto overflowHash=overflow.StateHash();sentinel=sentinelBefore;if(overflow.ApplyDirectDisplacementTick({1,{(std::numeric_limits<float>::max)(),0,0},0},empty,&sentinel)||overflow.StateHash()!=overflowHash||!SameResult(sentinel,sentinelBefore))return Fail("derived position overflow was committed");

    CollisionWorld3D benchmarkWorld;for(std::size_t i=0;i<128;++i)benchmarkWorld.CreateBox({{{1000.f+float(i)*3,0,0},{.5f,.5f,.5f}},1,CollisionLayerAll3D,i,false});CharacterController3D benchmark;if(!benchmark.PrepareDirectDisplacement(128))return Fail("benchmark prepare failed");benchmark.Reset({});constexpr std::size_t Iterations=10000;std::vector<long long> samples;samples.reserve(Iterations);const auto allocationsBefore=allocationCount.load();for(std::size_t i=0;i<Iterations;++i){const auto begin=std::chrono::steady_clock::now();if(!benchmark.ApplyDirectDisplacementTick({i+1,{.0001f,0,0},.00001f},benchmarkWorld,{},&result))return Fail("benchmark evaluate failed");samples.push_back(std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-begin).count());}const auto allocationsAfter=allocationCount.load();std::sort(samples.begin(),samples.end());const auto p95=samples[(samples.size()*95+99)/100-1];if(allocationsAfter!=allocationsBefore||p95>100000)return Fail("direct displacement allocation/performance gate failed");const auto retained=benchmark.MemoryStats();const auto released=benchmark.TrimUnusedMemory();const auto trimmed=benchmark.MemoryStats();if(!retained.retainedCapacityBytes||!released||trimmed.retainedCapacityBytes>=retained.retainedCapacityBytes||trimmed.lastReleasedBytes!=released||!trimmed.trimCount)return Fail("direct scratch lifecycle failed");
    std::cout<<"Character direct displacement smoke passed p95Ns="<<p95<<" allocations="<<(allocationsAfter-allocationsBefore)<<" hash="<<result.deterministicHash<<'\n';return 0;
}
